/**
 * A nadadeira da baleia-corcunda — os tubérculos que adiam o estol.
 *
 * O bordo de ataque da nadadeira é serrilhado, e as saliências dividem a água em
 * filetes que continuam colados à superfície mesmo num ângulo alto. É a razão de
 * a corcunda, do tamanho que é, fazer curvas fechadas atrás de um cardume.
 *
 * A cena mostra o que a leitura não consegue: **as linhas de corrente colando ou
 * descolando**. No estol elas se soltam do dorso e viram um rastro de
 * redemoinhos — e a seta da sustentação despenca junto. É a única forma de o
 * "os tubérculos só ADIAM o estol, não o impedem" virar uma coisa vista.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  setaCheia,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const NADADEIRA = '#3d4a63';
const NADADEIRA_CLARA = '#5a6b8a';

const sustentacao: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /**
   * O perfil em corte, com os tubérculos no bordo de ataque.
   *
   * Desenhado no sistema do perfil (corda ao longo de x, de 0 a 1); quem gira é
   * o `ctx`, para que as linhas de corrente sejam calculadas em coordenadas de
   * tela sem ter de desfazer a rotação.
   */
  function perfil(ctx: CanvasRenderingContext2D, corda: number): void {
    const espessura = corda * 0.14;

    ctx.beginPath();
    ctx.moveTo(0, 0);
    // Dorso: sobe rápido e cai devagar até o bordo de fuga.
    ctx.bezierCurveTo(corda * 0.14, -espessura, corda * 0.5, -espessura * 0.95, corda, 0);
    // Ventre, quase reto.
    ctx.bezierCurveTo(corda * 0.5, espessura * 0.36, corda * 0.16, espessura * 0.5, 0, 0);
    ctx.closePath();

    const volume = ctx.createLinearGradient(0, -espessura, 0, espessura);
    volume.addColorStop(0, NADADEIRA_CLARA);
    volume.addColorStop(1, NADADEIRA);
    ctx.fillStyle = volume;
    ctx.fill();

    // Os tubérculos: as bolhas do bordo de ataque, o traço da corcunda. Ficam
    // meio para FORA do perfil, senão somem dentro da própria silhueta.
    ctx.fillStyle = '#8fa3c4';
    ctx.strokeStyle = NADADEIRA;
    ctx.lineWidth = 1;
    const quantos = 4;
    for (let i = 0; i < quantos; i++) {
      const u = (i + 0.5) / quantos;
      ctx.beginPath();
      ctx.arc(
        -espessura * 0.18,
        -espessura * 0.55 + u * espessura * 1.05,
        espessura * 0.3,
        0,
        Math.PI * 2,
      );
      ctx.fill();
      ctx.stroke();
    }
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const ataque = limitar(numeroDe(valores, 'a', 0), 0, 30);
    const forca = limitar(numeroDe(info, 'liftPct', 0), 0, 100);
    const estol = info.estol === true;
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : estol ? cor.erro : cor.azul;

    titulo(ctx, L, A, 'O fluxo colado é o que sustenta');

    const cx = L * 0.44;
    // A nadadeira mora na metade de baixo do quadro: a seta da sustentação sobe
    // dela, e a 99% ela precisa de altura para significar alguma coisa.
    const cy = A * 0.55;
    const corda = Math.min(L * 0.42, A * 0.58);
    const radianos = (ataque * Math.PI) / 180;

    // ── As linhas de corrente ─────────────────────────────────────────────
    const x0 = L * 0.04;
    const x1 = L * 0.96;
    const linhas = 7;

    for (let n = 0; n < linhas; n++) {
      const alturaBase = A * 0.3 + (n * A * 0.45) / (linhas - 1);
      // A linha que passa rente ao dorso é a que descola primeiro.
      const rente = Math.abs(alturaBase - (cy - corda * 0.1)) < A * 0.09;

      ctx.strokeStyle = rente && estol ? cor.erro : cor.azulClaro;
      ctx.lineWidth = rente ? 2.4 : 1.5;
      ctx.globalAlpha = rente ? 0.95 : 0.5;
      ctx.lineJoin = 'round';
      ctx.beginPath();

      for (let i = 0; i <= 140; i++) {
        const u = i / 140;
        const x = x0 + u * (x1 - x0);

        // Perto do perfil a linha é empurrada; o desvio some ao se afastar.
        const dx = x - cx;
        const proximidade = Math.exp(-((dx / (corda * 0.55)) ** 2));
        const desvio = -Math.sin(radianos) * corda * 0.42 * proximidade;

        // Depois do bordo de fuga, no estol, a esteira vira turbulência.
        const esteira =
          estol && dx > 0 && rente
            ? Math.sin(u * 26 - t * 6) * A * 0.045 * limitar(dx / (corda * 0.6), 0, 1)
            : 0;

        const y = alturaBase + desvio + esteira;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // ── A nadadeira ───────────────────────────────────────────────────────
    ctx.save();
    ctx.translate(cx - corda * 0.35, cy);
    // Ângulo de ataque: o bordo de ataque sobe, e o de fuga desce.
    ctx.rotate(-radianos);
    perfil(ctx, corda);
    ctx.restore();

    // ── A seta da sustentação ─────────────────────────────────────────────
    const miudo = limitar(A * 0.032, 8, 11);
    const partida = cy - corda * 0.18;
    // O teto da seta é o pé do título: a 99% ela e o rótulo subiam por cima dele.
    const teto = A * 0.185 + miudo * 1.8;
    const alturaSeta = Math.min((A * 0.3 * forca) / 100, partida - teto);

    if (forca > 2 && alturaSeta > 4) {
      setaCheia(ctx, cx, partida, cx, partida - alturaSeta, tinta, 3.4);
    }
    etiqueta(
      ctx,
      estol ? 'estol!' : `sustentação ${Math.round(forca)}%`,
      cx,
      Math.max(teto, partida - alturaSeta - miudo * 1.6),
      miudo,
      tinta,
      800,
    );

    // ── A régua do ângulo, com a faixa boa marcada ────────────────────────
    const yRegua = A * 0.81;
    const rx0 = L * 0.08;
    const rx1 = L * 0.92;
    const altura = limitar(A * 0.035, 6, 11);
    const ax = (graus: number): number => rx0 + (limitar(graus, 0, 30) / 30) * (rx1 - rx0);

    retangulo(ctx, rx0, yRegua, rx1 - rx0, altura, altura / 2, cor.palha, cor.trilho, 1);
    // A faixa de sustentação máxima, e a zona de estol logo em seguida.
    retangulo(ctx, ax(16), yRegua, ax(22) - ax(16), altura, 0, 'rgb(47 143 92 / 45%)');
    retangulo(ctx, ax(24), yRegua, ax(30) - ax(24), altura, 0, 'rgb(201 74 69 / 35%)');

    ctx.fillStyle = tinta;
    ctx.beginPath();
    ctx.moveTo(ax(ataque), yRegua - 4);
    ctx.lineTo(ax(ataque) - 5, yRegua - 12);
    ctx.lineTo(ax(ataque) + 5, yRegua - 12);
    ctx.closePath();
    ctx.fill();

    texto(ctx, `${Math.round(ataque)}°`, ax(ataque), yRegua - miudo * 1.9, miudo, {
      cor: tinta,
      peso: 800,
    });
    texto(ctx, 'ângulo de ataque', rx0, yRegua + altura + miudo * 1.1, miudo * 0.9, {
      cor: cor.fraco,
      peso: 600,
      alinhamento: 'left',
    });
    texto(ctx, 'estol', ax(27), yRegua + altura + miudo * 1.1, miudo * 0.9, {
      cor: cor.erro,
      peso: 700,
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Sustentação máxima: o fluxo continua colado ✔',
      estol
        ? 'O fluxo descolou — os tubérculos adiam o estol, não o impedem.'
        : 'Incline mais a nadadeira para ganhar força.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default sustentacao;
